ALTER TABLE public.user_portal_preferences ADD COLUMN high_contrast boolean NOT NULL DEFAULT false;
ALTER TABLE public.user_portal_preferences DROP CONSTRAINT IF EXISTS user_portal_preferences_interface_density_check;
ALTER TABLE public.user_portal_preferences ADD CONSTRAINT user_portal_preferences_interface_density_check CHECK(interface_density IN ('compact','standard','comfortable','extra_large'));
ALTER TABLE public.workspaces ADD COLUMN provider_subtype text NOT NULL DEFAULT 'nemt_business' CHECK(provider_subtype IN ('nemt_business','independent_contractor')), ADD COLUMN provider_subtype_selected_at timestamptz, ADD COLUMN pickup_delay_minutes integer CHECK(pickup_delay_minutes BETWEEN 1 AND 120);
ALTER TABLE public.vehicles ADD COLUMN vehicle_category text CHECK(vehicle_category IN ('ambulatory','wheelchair','stretcher','other')), ADD COLUMN make text, ADD COLUMN model text, ADD COLUMN model_year integer CHECK(model_year BETWEEN 1900 AND 2100), ADD COLUMN accessibility_equipment text, ADD COLUMN evidence_status text NOT NULL DEFAULT 'under_review' CHECK(evidence_status IN ('missing','present','expired','under_review','satisfied'));
COMMENT ON COLUMN public.vehicles.evidence_status IS 'Platform-attested vehicle requirement status; upload alone never satisfies requirements.';
CREATE FUNCTION public.pass4p_workspace_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='UPDATE' AND (NEW.provider_subtype IS DISTINCT FROM OLD.provider_subtype OR NEW.provider_subtype_selected_at IS DISTINCT FROM OLD.provider_subtype_selected_at) AND coalesce(current_setting('app.provider_subtype_write',true),'')<>'true' THEN RAISE EXCEPTION 'Use provider setup subtype selection'; END IF;
 IF NEW.provider_subtype='independent_contractor' AND NEW.account_type<>'provider' THEN RAISE EXCEPTION 'Provider account required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pass4p_workspace_guard BEFORE UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.pass4p_workspace_guard();
CREATE FUNCTION public.select_provider_subtype(_ws uuid,_subtype text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.workspaces; BEGIN
 SELECT * INTO w FROM public.workspaces WHERE id=_ws FOR UPDATE;
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND p.onboarding_completed_at IS NULL) OR w.account_type<>'provider' OR w.status<>'active' OR w.is_test_account THEN RAISE EXCEPTION 'Incomplete active provider owner setup required'; END IF;
 IF _subtype NOT IN ('nemt_business','independent_contractor') OR w.provider_subtype_selected_at IS NOT NULL THEN RAISE EXCEPTION 'Subtype already selected or invalid'; END IF;
 IF EXISTS(SELECT 1 FROM public.vehicles WHERE workspace_id=_ws) OR EXISTS(SELECT 1 FROM public.provider_network_profiles WHERE workspace_id=_ws) THEN RAISE EXCEPTION 'Established provider configuration cannot be reclassified'; END IF;
 PERFORM set_config('app.provider_subtype_write','true',true); UPDATE public.workspaces SET provider_subtype=_subtype,provider_subtype_selected_at=now() WHERE id=_ws;
 END $$;
REVOKE ALL ON FUNCTION public.select_provider_subtype(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.select_provider_subtype(uuid,text) TO authenticated;
CREATE FUNCTION public.pass4p_service_eligible(_ws uuid,_service text,_vehicle uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=_ws AND w.status='active' AND NOT w.is_test_account AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=w.id AND (_vehicle IS NULL OR v.id=_vehicle) AND v.status='active' AND v.vehicle_category IS NOT NULL AND _service=ANY(v.service_capabilities) AND v.capacity>0 AND (lower(_service)<>'wheelchair' OR v.wheelchair_capacity>0) AND (w.provider_subtype='nemt_business' OR (lower(_service)='ambulatory' AND v.vehicle_category='ambulatory' AND v.make IS NOT NULL AND v.model IS NOT NULL AND v.model_year IS NOT NULL AND nullif(trim(v.plate),'') IS NOT NULL AND v.evidence_status='satisfied')))
 AND (w.provider_subtype='nemt_business' OR (lower(_service)='ambulatory' AND w.provider_verified AND public.provider_has_valid_credentials((SELECT user_id FROM public.workspace_members WHERE workspace_id=w.id AND role='owner' AND NOT is_contractor AND removed_at IS NULL LIMIT 1)) AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['driver_license','auto_insurance','w9']) k WHERE NOT EXISTS(SELECT 1 FROM public.provider_credentials c WHERE c.workspace_id=w.id AND c.kind=k AND c.doc_path IS NOT NULL AND c.accuracy_attested_at IS NOT NULL AND c.lifecycle_state='current' AND c.effective_at<=current_date AND c.expires_at>=current_date AND (k<>'auto_insurance' OR (nullif(c.insurance_carrier,'') IS NOT NULL AND nullif(c.policy_reference,'') IS NOT NULL AND c.coverage_cents>0))))))) $$;
REVOKE ALL ON FUNCTION public.pass4p_service_eligible(uuid,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pass4p_service_eligible(uuid,text,uuid) TO authenticated,service_role;
CREATE FUNCTION public.pass4p_vehicle_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE subtype text; BEGIN
 SELECT provider_subtype INTO subtype FROM public.workspaces WHERE id=NEW.workspace_id;
 IF TG_OP='INSERT' AND NEW.evidence_status<>'under_review' AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Vehicle review is platform controlled'; END IF;
 IF TG_OP='UPDATE' AND NEW.evidence_status IS DISTINCT FROM OLD.evidence_status AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Vehicle review is platform controlled'; END IF;
 IF subtype='independent_contractor' THEN
 IF NEW.service_capabilities && ARRAY['wheelchair','stretcher']::text[] OR NEW.vehicle_category IN ('wheelchair','stretcher') THEN RAISE EXCEPTION 'Contractors support Ambulatory only'; END IF;
 IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM public.vehicles WHERE workspace_id=NEW.workspace_id) THEN RAISE EXCEPTION 'Contractor primary vehicle already exists'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER pass4p_vehicle_guard BEFORE INSERT OR UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.pass4p_vehicle_guard();
CREATE FUNCTION public.pass4p_profile_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE subtype text;s text; BEGIN
 SELECT provider_subtype INTO subtype FROM public.workspaces WHERE id=NEW.workspace_id;
 IF subtype='independent_contractor' AND (NEW.service_types && ARRAY['wheelchair','stretcher']::text[] OR NEW.medical_delivery) THEN RAISE EXCEPTION 'Independent Contractor supports Ambulatory only; wheelchair/stretcher require eligible NEMT business evidence'; END IF;
 IF NEW.visible THEN FOREACH s IN ARRAY NEW.service_types LOOP IF NOT public.pass4p_service_eligible(NEW.workspace_id,s) THEN RAISE EXCEPTION 'Vehicle and applicable platform evidence required before advertising'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER pass4p_profile_guard BEFORE INSERT OR UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.pass4p_profile_guard();
CREATE FUNCTION public.pass4p_trip_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid; BEGIN
 ws:=NEW.network_provider_workspace_id;
 IF ws IS NULL AND NEW.assigned_to IS NOT NULL THEN SELECT workspace_id INTO ws FROM public.workspace_members WHERE user_id=NEW.assigned_to AND removed_at IS NULL AND EXISTS(SELECT 1 FROM public.workspaces WHERE id=workspace_id AND account_type='provider') ORDER BY role='owner' DESC LIMIT 1; END IF;
 IF ws IS NOT NULL AND (TG_OP='INSERT' OR NEW.assigned_to IS DISTINCT FROM OLD.assigned_to OR NEW.network_provider_workspace_id IS DISTINCT FROM OLD.network_provider_workspace_id OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id OR NEW.transport_type IS DISTINCT FROM OLD.transport_type) AND NOT public.pass4p_service_eligible(ws,NEW.transport_type,NEW.vehicle_id) THEN RAISE EXCEPTION 'Provider vehicle/service evidence is not eligible'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pass4p_trip_guard BEFORE INSERT OR UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.pass4p_trip_guard();